Definition ref_reserved : list (Z * Z) := rband hceil :: [(0x10000, 0x1b000); (0x2b000, 0x53000); (0x7e000, 0x6000); (0x84000, 0x34000)].

Lemma reservedZ_ref : rband hceil :: reservedZ usegs = ref_reserved.
Proof. try hcb. unfold ref_reserved. f_equal. all: vm_compute; reflexivity. Qed.

